import json,re,collections
rows=[json.loads(l) for l in open('commits.jsonl',encoding='utf-8') if l.strip()]
pat=re.compile(r'^([a-z]+)(?:\(([^()\s]+)\))?(!)?: (.+)$')
types=collections.Counter(); scopes=collections.Counter(); brk=[]; internal=[]
for r in rows:
    h=r['message'].splitlines()[0]; m=pat.match(h)
    if m:
        t,sc,b,s=m.groups(); types[t]+=1; scopes[sc or '(none)']+=1
        if b: brk.append((r,h))
        if sc=='internal': internal.append((r,h))
print('types',types)
print('scopes',scopes)
print('breaking',len(brk))
for r,h in brk: print(' B',r['hash'][:7],repr(h),'|',r['author'])
print('internal',len(internal))
for r,h in internal: print(' I',r['hash'][:7],repr(h))
print('--- Fixes lines ---')
for r in rows:
    for ln in r['message'].splitlines()[1:]:
        if 'fix' in ln.lower() or 'revert' in ln.lower():
            print(r['hash'][:7], '|', repr(ln))
print('--- coauthor lines ---')
for r in rows:
    for ln in r['message'].splitlines()[1:]:
        if 'co-author' in ln.lower(): print(r['hash'][:7],'|',repr(ln))
