        for ln in r['message'].splitlines():
            m=re.fullmatch(r'This reverts commit ([0-9a-f]{40})\.',ln.strip())
            if m: named.add(m.group(1))
mail={}
for ln in open('.mailmap',encoding='utf-8'):
    ln=ln.strip()
    if not ln or ln.startswith('#'): continue
    emails=re.findall(r'<([^>]+)>',ln); name=ln.split('<')[0].strip()
    for e in emails: mail[e]=name
def canon(n,e): return mail.get(e,n)
def isbot(n): return n.endswith('[bot]')
cands=[]
for r in rows:
    h=r['message'].splitlines()[0]; m=pat.match(h)
    if not m: continue
    t,sc,b,s=m.groups(); sc=sc or 'general'
    if r['hash'] in named: continue
    if b: sec='Breaking changes'
    elif t in ('feat','fix','perf'): sec={'feat':'Features','fix':'Fixes','perf':'Features'}[t]
    else: continue
    if sc=='internal' and not b: continue
    if sc=='deps': sc='dependencies'
    s=s[0].upper()+s[1:]
    if s.endswith('.'): s=s[:-1]
    if t=='perf': s=s+' [perf]'
    refs=[]
    if t=='fix':
        for ln in r['message'].splitlines()[1:]:
            mm=re.fullmatch(r'Fixes #(\d+)',ln)
            if mm: refs.append(int(mm.group(1)))
    cands.append({'sec':sec,'scope':sc,'sum':s,'refs':refs,'r':r,'ts':datetime.fromisoformat(r['date'])})
groups=collections.defaultdict(list)
for c in cands: groups[(c['sec'],c['scope'],c['sum'])].append(c)
entries=[]
for (sec,sc,s),v in groups.items():
    v.sort(key=lambda c:c['ts'],reverse=True)
    refs=[]
    for c in v:
        for n in c['refs']:
            if n not in refs: refs.append(n)
    entries.append({'sec':sec,'scope':sc,'sum':s,'refs':refs,
                    'hashes':[c['r']['hash'][:7] for c in v],'newest':v[0]['ts']})
order={'Breaking changes':0,'Features':1,'Fixes':2}
entries.sort(key=lambda e:(order[e['sec']],e['scope'],-e['newest'].timestamp()))
def render(e):
    refs=''.join(f' (#{n})' for n in e['refs'])
    suffix=f"{refs} ({', '.join(e['hashes'])})"
    pre=f"- **{e['scope']}:** "
    s=e['sum']; line=pre+s+suffix
    if len(line)>100:
        avail=100-len(pre)-len(suffix)-1
        s=s[:avail].rstrip(' ')+'\u2026'
        line=pre+s+suffix
    return line
lines=['# Release 4.2.0','']
secs=[('Breaking changes',[e for e in entries if e['sec']=='Breaking changes']),
      ('Features',[e for e in entries if e['sec']=='Features']),
      ('Fixes',[e for e in entries if e['sec']=='Fixes'])]
counts=collections.Counter(); authored=set()
for c in cands:
    r=c['r']; people=set(); a=canon(r['author'],r['email'])
    if not isbot(a): people.add(a); authored.add(a)
    for ln in r['message'].splitlines()[1:]:
        m=re.fullmatch(r'Co-authored-by: (.*?) <([^>]+)>',ln)
        if m:
            n=canon(m.group(1),m.group(2))
            if not isbot(n): people.add(n)
    for p in people: counts[p]+=1
contrib=sorted(((p,counts[p]) for p in authored),key=lambda x:(-x[1],x[0]))
for title,es in secs:
    if not es: continue
    lines.append('## '+title); lines.append('')
    lines.extend(render(e) for e in es); lines.append('')
lines.append('## Contributors'); lines.append('')
lines.extend(f'- {p} ({n})' for p,n in contrib)
text='\n'.join(lines)+'\n'
with open('RELEASE_NOTES.md','w',encoding='utf-8',newline='\n') as f:
    f.write(text)
print(len(text), len(text.splitlines()), max(len(l) for l in text.splitlines()))
print('equal preview:', text==open('/tmp/preview.txt',encoding='utf-8').read())
